import RNA, random, sys, time
target='(.(((..(((((....(((((......))))))))))((((...((((.....))))))))(((..(((....)))))).(((...((((...((((......))))))))(((..(((.....))))))((.((....)))).((((....(((..(((......))))))((.((.....))))(((....))).(((((.....((.((......))))(((.....)))((....)).((((((......(((......)))((.....))...(((((((...))))))).......))))))......))))).....))))....)))...)))..)...(.((.((((....((....))((....))((((((...)))))).)))))).)'
n=len(target)
def pairs(db):
    st=[]; ps=set()
    for i,c in enumerate(db):
        if c=='(': st.append(i)
        elif c==')': ps.add((st.pop(),i))
    return ps
tp=pairs(target)
pm=[-1]*n
for i,j in tp: pm[i]=j; pm[j]=i
comp={'A':'U','U':'A','G':'C','C':'G'}
def bp_dist(s): return len(tp^pairs(s))
def fold(seq):
    return RNA.fold_compound(seq).mfe()[0]
def score(seq): return bp_dist(fold(seq))

def init_seq():
    s=['A']*n
    for i in range(n):
        if pm[i]>i: s[i]='G'; s[pm[i]]='C'
    return ''.join(s)

def repair_step(cur, ss):
    sp=pairs(ss)
    missing=tp-sp; spur=sp-tp
    cand=list(cur)
    acts=[]
    if missing:
        for (i,j) in list(missing):
            acts.append(('M',i,j))
    if spur:
        for (i,j) in list(spur):
            acts.append(('S',i,j))
    return acts

random.seed()
best_global=init_seq()
bs_global=score(best_global)
t0=time.time()
restart=0
while time.time()-t0<140:
    restart+=1
    cur=list(init_seq()) if restart%3==0 else list(best_global)
    # add some randomization on restart
    if restart>1:
        for _ in range(random.randint(3,20)):
            k=random.randint(0,n-1)
            cur[k]=random.choice('ACGU')
    cur=''.join(cur); curs=score(cur)
    local_t=time.time()
    while time.time()-local_t<3 and curs>0:
        ss=fold(cur)
        acts=repair_step(cur,ss)
        cand=list(cur)
        # apply multiple repairs + random
        napply=min(len(acts), random.randint(1,4))
        for a in random.sample(acts, napply):
            typ,i,j=a
            if typ=='M':
                cand[i]='G'; cand[j]='C'
            else:
                # break with mismatch
                b=random.choice(['A','A','U'])
                cand[i]=b; cand[j]=comp[b] if random.random()<0.3 else b
        # occasional random
        if random.random()<0.3:
            k=random.randint(0,n-1)
            cand[k]=random.choice('ACGU')
        ns=''.join(cand)
        nss=score(ns)
        if nss<curs or (nss==curs and random.random()<0.3):
            cur=ns; curs=nss
            if nss<bs_global:
                best_global=ns; bs_global=nss
                print('restart',restart,'best',bs_global,file=sys.stderr)
        elif nss==curs and random.random()<0.1:
            cur=ns
print('restarts',restart,'best',bs_global,file=sys.stderr)
print(best_global)
