def pairs(db):
    st=[]; ps=set()
    for i,c in enumerate(db):
        if c=='(': st.append(i)
        elif c==')': ps.add((st.pop(),i))
    return ps
tp=pairs(target)
pm=[-1]*n
for i,j in tp: pm[i]=j; pm[j]=i
comp={'A':'U','U':'A','G':'C','C':'G'}
def bp_dist(ss): return len(tp^pairs(ss))
def fold(seq): return RNA.fold_compound(seq).mfe()[0]
def score(seq): return bp_dist(fold(seq))

cur=''
