print('start',curs,file=sys.stderr)

random.seed(55)
best=cur; bs=curs
t0=time.time()
while time.time()-t0<140 and curs>0:
    ss=fold(cur)
    sp=pairs(ss)
    missing=tp-sp; spur=sp-tp
    # greedy: try all single-pair repairs
